parameters.jsCode:
// Validacion de lo que llega. Un webhook es una puerta abierta: lo que
// entra por ahi no se usa sin mirarlo primero.
//
// Alertmanager manda {status, alerts:[{labels, annotations, startsAt...}]}.
// Si falta algo de eso, no es Alertmanager y se descarta.

const cuerpo = $input.first().json.body ?? $input.first().json;

if (!cuerpo || typeof cuerpo !== 'object') {
  throw new Error('El cuerpo no es un objeto JSON.');
}
if (!Array.isArray(cuerpo.alerts) || cuerpo.alerts.length === 0) {
  throw new Error('No viene el arreglo "alerts".');
}
if (!['firing', 'resolved'].includes(cuerpo.status)) {
  throw new Error(`Estado desconocido: ${cuerpo.status}`);
}

const LARGO_MAX = 500;
const limpiar = (t) => String(t ?? '')
  .replace(/[\u0000-\u001f]/g, ' ')   // control: nada de saltos raros
  .slice(0, LARGO_MAX)
  .trim();

return cuerpo.alerts.map((a) => {
  const etiquetas = a.labels || {};
  const textos = a.annotations || {};
  if (!etiquetas.alertname) {
    throw new Error('Una alerta no trae alertname.');
  }
  // Las reglas de este proyecto nombran sus etiquetas y anotaciones en
  // castellano: severidad (critica|alta|media), resumen, detalle y una o mas
  // claves que empiezan con por_que_. Los nombres estandar de Prometheus
  // (severity, summary, description) se aceptan como respaldo, para que el
  // flujo sirva igual en otra instalacion.
  //
  // Esto no es un detalle: cuando el flujo leia solo los nombres en ingles, una
  // alerta real llegaba con severidad "media" por defecto y el filtro de
  // criticas la descartaba sin abrir nada.
  const sev = limpiar(etiquetas.severidad || etiquetas.severity || 'media').toLowerCase();
  const severidad = ['critica', 'critical'].includes(sev) ? 'critica' : sev;

  // Las justificaciones del umbral son varias y cada regla las llama distinto
  // (por_que_un_minuto, por_que_existe...). Se juntan todas.
  const porques = Object.keys(textos)
    .filter((k) => k.startsWith('por_que'))
    .map((k) => limpiar(textos[k]))
    .filter(Boolean);

  return {
    json: {
      estado: cuerpo.status,
      nombre: limpiar(etiquetas.alertname),
      severidad,
      servicio: limpiar(etiquetas.job || etiquetas.instance || 'desconocido'),
      resumen: limpiar(textos.resumen || textos.summary || etiquetas.alertname),
      detalle: limpiar(textos.detalle || textos.description || ''),
      porque: porques.join(' ') || limpiar(textos.umbral || textos.justificacion || ''),
      desde: limpiar(a.startsAt || ''),
      // La huella es lo que evita abrir 40 incidencias por la misma caida.
      huella: `${limpiar(etiquetas.alertname)}|${limpiar(etiquetas.job || etiquetas.instance || '')}`,
    },
  };
});

// Se decide si hay que abrir una incidencia nueva o si ya existe una por
// lo mismo. El criterio es la huella (alerta + servicio) buscada en el
// resumen de las incidencias abiertas.
//
// Si la consulta a Mantis fallo, abiertas queda vacio y se abre igual.
// Entre un duplicado y una caida sin registrar, el duplicado es mejor.

const alerta = $('Es critica y esta activa').first().json;
const respuesta = $input.first().json;
const abiertas = Array.isArray(respuesta?.issues) ? respuesta.issues : [];

const yaExiste = abiertas.find((i) =>
  String(i.summary || '').includes(`[${alerta.huella}]`) &&
  !['closed', 'resolved'].includes(String(i.status?.name || '').toLowerCase())
);

return [{
  json: {
    ...alerta,
    duplicada: Boolean(yaExiste),
    idExistente: yaExiste ? yaExiste.id : null,
    consultaFallo: !Array.isArray(respuesta?.issues),
  },
}];

